#!/usr/bin/env node
/**
 * Generate `examples/demo/src/fixtures.generated.js` from the round-trip
 * fixture corpus verveguy/liminis-editor#1 landed at
 * `src/app/mapper/__tests__/fixtures/roundtrip/`.
 *
 * The demo shell must not import from `@liminis/editor/src/...` or any
 * relative path reaching into the package's `src/` (FR-008), so it cannot
 * read the corpus directly. This script does the reading at build time and
 * emits a plain, corpus-free JS module the demo imports like any other local
 * file. See docs/decisions/adr-081.md for the full rationale.
 *
 * The generated file is gitignored — `pnpm demo` and `scripts/build-examples.mjs`
 * both run this script before building or serving the demo, so there is no
 * code path that consumes a stale copy.
 *
 * Discovery mirrors `roundtrip-test-utils.ts`'s `discoverFixtures`: any
 * `*.md` file under the corpus, excluding `*.expected.md` sidecars and
 * `README.md`. Fixtures with a companion `.error.txt` sidecar are expected to
 * throw on import (`roundTrip()` never produces a stable document for them),
 * so they are excluded here too, mirroring `node-class-completeness.test.ts`'s
 * own skip logic.
 *
 * Usage: `node scripts/generate-demo-fixtures.mjs`
 */
import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs'
import { dirname, join, relative, resolve, sep } from 'node:path'
import { fileURLToPath } from 'node:url'

const REPO_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const FIXTURES_DIR = join(REPO_ROOT, 'src', 'app', 'mapper', '__tests__', 'fixtures', 'roundtrip')
const OUT_FILE = join(REPO_ROOT, 'examples', 'demo', 'src', 'fixtures.generated.js')
// Documents that are not round-trip fixtures but are still worth showing in the
// demo. `all-the-things.md` is the shared sample both shells load: every
// construct the package supports, in one document. It deliberately does NOT
// live in the corpus — it is a demonstration, not a fidelity assertion, and it
// currently exercises several open round-trip defects.
const SHARED_DIR = join(REPO_ROOT, 'examples', 'shared')

function discoverFixtures(dir) {
  const entries = []

  function walk(current) {
    for (const entry of readdirSync(current, { withFileTypes: true })) {
      const fullPath = join(current, entry.name)
      if (entry.isDirectory()) {
        walk(fullPath)
        continue
      }
      if (!entry.isFile()) continue
      if (!entry.name.endsWith('.md')) continue
      if (entry.name.endsWith('.expected.md')) continue
      if (entry.name === 'README.md') continue

      const stem = fullPath.slice(0, -'.md'.length)
      const errorPath = `${stem}.error.txt`
      // Expected to throw on import — never reaches a stable document, so
      // there is nothing renderable to hand the demo.
      if (existsSync(errorPath)) continue

      const name = relative(dir, stem).split(sep).join('/')
      entries.push({
        name,
        group: name.includes('/') ? name.split('/')[0] : 'general',
        markdown: readFileSync(fullPath, 'utf8'),
      })
    }
  }

  walk(dir)
  entries.sort((a, b) => a.name.localeCompare(b.name))
  return entries
}

const fixtures = discoverFixtures(FIXTURES_DIR)

// Shared sample documents lead the list — they are what a first-time reader
// should see, ahead of several dozen narrow regression fixtures.
if (existsSync(SHARED_DIR)) {
  fixtures.unshift(...discoverFixtures(SHARED_DIR).map((entry) => ({ ...entry, group: 'sample' })))
}

if (fixtures.length === 0) {
  console.error(`no fixtures discovered under ${relative(REPO_ROOT, FIXTURES_DIR)}`)
  process.exit(1)
}

const banner = `// Generated by scripts/generate-demo-fixtures.mjs from
// src/app/mapper/__tests__/fixtures/roundtrip/ (verveguy/liminis-editor#1).
// Do not edit by hand — this file is gitignored and regenerated on every
// \`pnpm demo\` / \`pnpm build:examples\` run. See docs/decisions/adr-081.md.
`

const body = `export const fixtures = ${JSON.stringify(fixtures, null, 2)}\n`

mkdirSync(dirname(OUT_FILE), { recursive: true })
writeFileSync(OUT_FILE, banner + body)

console.log(`Wrote ${fixtures.length} fixture(s) to ${relative(REPO_ROOT, OUT_FILE)}`)
